#include <chrono>
#include <iostream>

int main() {
    using namespace std::chrono_literals;
    auto lesson = 45min;
    auto halfmin = 0.5min;
    std::cout << "One lesson is " << lesson.count()
              << " minutes"
                 " ("
              << lesson << ")\n"
              << "Half a minute is " << halfmin.count()
              << " minutes"
                 " ("
              << halfmin << ")\n";
}
